I think this should follow your use case: https://codesandbox.io/s/amazing-ganguly-69jxx?file=/src/app.js

1. loop to add all widgets
2. conditionally do css in a custom widget's `render` function

```js
const toggles = [
  { attribute: 'brand', value: 'Apple' },
  { attribute: 'brand', value: 'Samsung' },
  { attribute: 'brand', value: 'Samsung' },
  { attribute: 'brand', value: 'Samsung' },
];

function superPanel({ container, values }) {
  const containerNode = document.querySelector(container);
  return [
    ...values.map(({ attribute, value }) => {
      const toggleContainer = document.createElement('div');
      containerNode.appendChild(toggleContainer);

      return instantsearch.widgets.toggleRefinement({
        container: toggleContainer,
        attribute,
        templates: {
          labelText: `${value} {{count}}`,
        },
        on: value,
      });
    }),
    {
      init() {},
      render({ results }) {
        const facetValues = values.map(({ attribute, value }) => {
          const allValues = results.getFacetValues(attribute);
          return allValues.find(({ name }) => name === value) || {};
        });

        const shouldShow = facetValues.some(({ count }) => count > 0);

        containerNode.style.opacity = shouldShow ? 1 : 0.5;
        // alternative style:
        // containerNode.hidden = !shouldShow;
      },
    },
  ];
}

search.addWidgets(superPanel({container: ".search-panel__filters", values}))
```
